// Create
const createPayload = _PostFactory.default.createValid();
_JsonPlaceholderService.default.createPost(createPayload).then(createResponse => {
  expect(createResponse.status).to.eq(201);
  const createdId = createResponse.body.id;
  // Verify created
  _JsonPlaceholderService.default.getPostById(createdId).then(getResponse => {
    expect(getResponse.status).to.eq(200);
    // Update
    const updatePayload = _PostFactory.default.create();
    _JsonPlaceholderService.default.updatePost(createdId, updatePayload).then(updateResponse => {
      expect(updateResponse.status).to.eq(200);
      expect(updateResponse.body.title).to.eq(updatePayload.title);
      // Delete
      _JsonPlaceholderService.default.deletePost(createdId).then(deleteResponse => {
        expect(deleteResponse.status).to.eq(200);
      });
    });
  });
});
